program.compute:
options=read('/input/options')
result=[]
for r in options:
    if len(result)<2:
        result=result+[r['id']]
if not valid(result):
    result=[]
    for a in options:
        for b in options:
            if a['id']!=b['id'] and len(result)==0 and valid([a['id'],b['id']]):
                result=[a['id'],b['id']]

program.effects:
if exists('/output/selection'):
    result=read('/output/selection')
    if not valid(result):
        result=[]
else:
    if not valid(result):
        result=[]
    if len(result)>0:
        write('/output/selection',result)
if len(result)>0:
    r=receipt('report')
    if r=='success':
        pass
    elif r=='unknown':
        status('report')
    elif r=='unattempted' or r=='failure':
        if status('report')=='not_sent':
            send('report','team',result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

